spec fn nonneg(x: i64) -> bool { x >= 0 }

spec fn is_third(x: i64, r: i64) -> bool { 3 * r <= x && x < 3 * r + 3 }

#[effects(pure)]
#[uses(nonneg, is_third)]
fn third(x: i64) -> (r: i64)
    requires nonneg(x),
    ensures is_third(x, r),
{
    -1
}

